insert into public.roadtrip_routes (slug,title,description,cover_image_url,author_user_id,author_name,visibility,status,is_featured,tags,total_nights,country_codes,occasion,budget,stops) values
('irland-wild-atlantic-way','Wild Atlantic Way — Irlands wilder Westen','Von den Pubs in Galway über die Cliffs of Moher bis zu den bunten Häusern von Kinsale: fünf Tage Atlantikküste, Trad-Music-Sessions, Schafe auf Serpentinen und das beste Seafood der Insel.',null,null,'PD24 Redaktion','public','completed',true,array['europe','ireland','coast','nature','adventure','road-trip'],5,array['IE'],'tourism','medium',$$[{"citySlug":"ie-galway","cityLabel":"Galway","lat":53.2707,"lng":-9.0568,"nights":1,"planSummary":"Buntes Studentenstädtchen am Atlantik: Buskers im Latin Quarter, Kaffee am Spanish Arch und abends eine Trad-Session im Pub, die kein Ende nimmt.","plannedStops":[{"label":"Latin Quarter","hint":"Bunte Fassaden, Straßenmusiker und kleine Läden entlang der Quay Street","time":"14:00","itemName":"Latin Quarter Galway"},{"label":"Spanish Arch & Museum","hint":"Stadttor am Fluss Corrib mit dem Galway City Museum direkt dahinter","time":"15:30","itemName":"Spanish Arch"},{"label":"Salthill Promenade","hint":"Küstenspaziergang mit Blick auf die Galway Bay — am Ende gegen die Mauer treten, wie die Locals","time":"17:00","itemName":"Salthill Promenade"},{"label":"Seafood-Dinner","hint":"Preisgekröntes Lokal am Fluss mit Fokus auf irische Zutaten","time":"19:00","itemName":"Ard Bia at Nimmos"},{"label":"Trad-Session","hint":"Traditionspub von 1894, jeden Abend Live-Folk zwischen Whiskey-Regalen","time":"21:00","itemName":"Tigh Neachtain"}]},{"citySlug":"ie-doolin","cityLabel":"Doolin & Cliffs of Moher","lat":53.0645,"lng":-9.3773,"nights":1,"planSummary":"Die berühmteste Steilküste Irlands, dahinter die bizarre Karstlandschaft des Burren — und abends Fiddle und Guinness im Musikerdorf Doolin.","plannedStops":[{"label":"Cliffs of Moher","hint":"214 Meter senkrecht in den Atlantik — früh kommen, bevor die Busse anrollen","time":"09:30","itemName":"Cliffs of Moher"},{"label":"O'Briens Tower","hint":"Aussichtsturm von 1835 am höchsten Punkt der Klippen","time":"11:00","itemName":"O'Brien's Tower"},{"label":"Pub-Lunch","hint":"Seafood Chowder und Brown Bread im Pub von 1832","time":"13:00","itemName":"Gus O'Connor's Pub"},{"label":"Burren & Dolmen","hint":"Mondlandschaft aus Kalkstein mit dem 5.800 Jahre alten Portalgrab","time":"15:00","itemName":"Poulnabrone Dolmen"},{"label":"Abend-Session","hint":"Doolin gilt als Hauptstadt der irischen Traditionsmusik — Session ab 21 Uhr","time":"21:00","itemName":"McGann's Pub Doolin"}]},{"citySlug":"ie-dingle","cityLabel":"Dingle","lat":52.1409,"lng":-10.264,"nights":1,"planSummary":"Über den Conor Pass auf die Dingle-Halbinsel: der Slea Head Drive ist Irlands schönste Panoramastraße, danach Fish & Chips im Hafen und ein Pint zwischen Lederwaren bei Dick Mack's.","plannedStops":[{"label":"Slea Head Drive","hint":"Einspurige Küstenschleife mit Blick auf die Blasket Islands — im Uhrzeigersinn fahren","time":"09:30","itemName":"Slea Head Drive"},{"label":"Coumeenoole Beach","hint":"Wilde Bucht unter den Klippen, Drehort von Ryans Tochter","time":"11:30","itemName":"Coumeenoole Beach"},{"label":"Fish & Chips","hint":"Fangfrischer Fisch vom familieneigenen Trawler","time":"13:30","itemName":"The Fish Box Dingle"},{"label":"Eis-Pause","hint":"Kult-Eis aus Kerry-Milch, probiert die Sorte Meersalz","time":"15:30","itemName":"Murphy's Ice Cream Dingle"},{"label":"Pub-Abend","hint":"Halb Schusterwerkstatt, halb Whiskey-Bar — eine Institution seit 1899","time":"20:00","itemName":"Dick Mack's Pub"}]},{"citySlug":"ie-killarney","cityLabel":"Killarney","lat":52.0599,"lng":-9.5044,"nights":1,"planSummary":"Irlands ältester Nationalpark: viktorianisches Herrenhaus, Wasserfall im Regenwald-Grün, Burgruine am See und der berühmteste Aussichtspunkt des Ring of Kerry.","plannedStops":[{"label":"Muckross House","hint":"Viktorianisches Anwesen mit Gärten direkt am Muckross Lake","time":"09:30","itemName":"Muckross House"},{"label":"Torc Waterfall","hint":"20-Meter-Wasserfall im moosgrünen Wald, kurzer Anstieg zum Aussichtspunkt","time":"11:30","itemName":"Torc Waterfall"},{"label":"Seafood-Lunch","hint":"Fischtheke und Chowder der Fischerei-Familie Quinlan","time":"13:00","itemName":"Quinlan's Seafood Bar Killarney"},{"label":"Ross Castle","hint":"Turmburg aus dem 15. Jahrhundert am Ufer des Lough Leane","time":"15:00","itemName":"Ross Castle"},{"label":"Ladies View","hint":"Der Postkartenblick über die Seen von Killarney auf dem Ring of Kerry","time":"17:00","itemName":"Ladies View"}]},{"citySlug":"ie-kinsale","cityLabel":"Kinsale","lat":51.7059,"lng":-8.5222,"nights":1,"planSummary":"Finale im buntesten Hafenstädtchen Irlands: Gourmet-Hauptstadt, Sternfort über der Bucht und ein letzter Küstenspaziergang mit Blick auf die Segelboote.","plannedStops":[{"label":"Bunte Altstadt","hint":"Knallbunte Fassaden und Galerien — das Fotomotiv schlechthin","time":"10:00","itemName":"Kinsale Old Town"},{"label":"Charles Fort","hint":"Sternförmige Festung von 1682 hoch über der Hafeneinfahrt","time":"11:30","itemName":"Charles Fort Kinsale"},{"label":"Scilly Walk","hint":"Uferpfad von Summercove zurück in den Ort, Blick auf die Bucht","time":"13:00","itemName":"Scilly Walk Kinsale"},{"label":"Seafood-Klassiker","hint":"Das bekannteste Fischrestaurant der irischen Gourmet-Hauptstadt","time":"14:00","itemName":"Fishy Fishy Kinsale"},{"label":"Hafen-Ausklang","hint":"Pier Road entlang der Marina mit Blick auf die Segelboote","time":"16:30","itemName":"Kinsale Pier Road"}]}]$$),
('schweiz-alpenpaesse-grand-tour','Schweizer Alpenpässe — Vierwaldstättersee bis Lugano','Fünf Tage Schweiz in einem Bogen: Kapellbrücke in Luzern, Wasserfälle im Lauterbrunnental, Gletscherblicke am First, dann über Furka- und Grimselpass hinunter ans Palmenufer von Lugano.',null,null,'PD24 Redaktion','public','completed',true,array['europe','switzerland','nature','adventure','luxury','road-trip'],5,array['CH'],'tourism','high',$$[{"citySlug":"ch-luzern","cityLabel":"Luzern","lat":47.0502,"lng":8.3093,"nights":1,"planSummary":"Auftakt am Vierwaldstättersee: die hölzerne Kapellbrücke, Altstadtgassen mit bemalten Fassaden und zum Abschluss ein Uferspaziergang im Abendlicht.","plannedStops":[{"label":"Kapellbrücke","hint":"Die älteste überdachte Holzbrücke Europas mit Wasserturm — das Wahrzeichen","time":"14:00","itemName":"Kapellbrücke Luzern"},{"label":"Altstadt-Bummel","hint":"Bemalte Zunfthäuser am Weinmarkt und Hirschenplatz","time":"15:00","itemName":"Altstadt Luzern"},{"label":"Löwendenkmal","hint":"Der sterbende Löwe im Fels — laut Mark Twain das traurigste Denkmal der Welt","time":"16:30","itemName":"Löwendenkmal Luzern"},{"label":"Seepromenade","hint":"Blick über den Vierwaldstättersee auf Pilatus und Rigi","time":"17:30","itemName":"Nationalquai Luzern"},{"label":"Dinner am See","hint":"Traditionshaus mit Fischküche nahe der Reuss","time":"19:00","itemName":"Wirtshaus Taube Luzern"}]},{"citySlug":"ch-lauterbrunnen","cityLabel":"Lauterbrunnen","lat":46.5936,"lng":7.9081,"nights":1,"planSummary":"Das Tal der 72 Wasserfälle: der Staubbachfall stürzt 297 Meter frei über die Felswand, drinnen im Berg donnern die Trümmelbachfälle — dazu Wengen als autofreier Balkon.","plannedStops":[{"label":"Staubbachfall","hint":"Frei fallender Wasserfall direkt am Dorf — kurzer Aufstieg zur Felsnische","time":"09:30","itemName":"Staubbachfall"},{"label":"Trümmelbachfälle","hint":"Zehn Gletscherwasserfälle im Berginneren, per Tunnel-Lift erschlossen","time":"11:00","itemName":"Trümmelbachfälle"},{"label":"Mittag im Tal","hint":"Café mit Blick auf die Felswände des Tals","time":"13:00","itemName":"Airtime Cafe Lauterbrunnen"},{"label":"Wengen-Ausflug","hint":"Mit der Zahnradbahn ins autofreie Bergdorf mit Jungfrau-Blick","time":"14:30","itemName":"Wengen"},{"label":"Talwanderung","hint":"Ebener Talweg Richtung Stechelberg, die Wasserfälle immer im Blick","time":"17:00","itemName":"Talweg Lauterbrunnen–Stechelberg"}]},{"citySlug":"ch-grindelwald","cityLabel":"Grindelwald","lat":46.6244,"lng":8.0411,"nights":1,"planSummary":"Gletscherdorf unter der Eiger-Nordwand: Cliff Walk am First, Bergsee-Wanderung zum Bachalpsee und abends Fondue mit Blick auf die Wand.","plannedStops":[{"label":"First Cliff Walk","hint":"Stahlsteg an der Felskante mit Blick auf Eiger und Wetterhorn","time":"09:30","itemName":"First Cliff Walk Grindelwald"},{"label":"Bachalpsee","hint":"Wanderung vom First zum Bergsee, in dem sich das Schreckhorn spiegelt (ca. 1 Std.)","time":"11:00","itemName":"Bachalpsee"},{"label":"Bergrestaurant","hint":"Mittag auf 2.168 m mit Panoramaterrasse","time":"13:30","itemName":"Berggasthaus First"},{"label":"Gletscherschlucht","hint":"Steganlage durch die enge Schlucht des Unteren Grindelwaldgletschers","time":"16:00","itemName":"Gletscherschlucht Grindelwald"},{"label":"Fondue-Abend","hint":"Käsefondue im Chalet-Restaurant mit Blick zur Eiger-Nordwand","time":"19:00","itemName":"Restaurant Barrys Grindelwald"}]},{"citySlug":"ch-andermatt","cityLabel":"Andermatt & Furkapass","lat":46.6356,"lng":8.5939,"nights":1,"planSummary":"Der Pässe-Tag: über Grimsel- und Furkapass mit Blick auf den Rhonegletscher, die James-Bond-Kurven hinunter und durch die Schöllenenschlucht zur Teufelsbrücke.","plannedStops":[{"label":"Grimselpass","hint":"Stauseen-Panorama auf 2.164 m zwischen Berner Oberland und Wallis","time":"10:00","itemName":"Grimselpass"},{"label":"Rhonegletscher & Eisgrotte","hint":"Beim Hotel Belvédère in den Gletscher gehauene Eishöhle (saisonal)","time":"11:30","itemName":"Eisgrotte Rhonegletscher"},{"label":"Furkapass","hint":"Goldfinger-Drehort von 1964 — Serpentinen auf 2.429 m","time":"13:00","itemName":"Furkapass"},{"label":"Teufelsbrücke","hint":"Dramatische Brücken über die tosende Reuss in der Schöllenenschlucht","time":"15:30","itemName":"Teufelsbrücke Schöllenen"},{"label":"Dorfabend Andermatt","hint":"Urschner Spezialitäten im alten Dorfkern","time":"19:00","itemName":"Gasthaus Ochsen Andermatt"}]},{"citySlug":"ch-lugano","cityLabel":"Lugano","lat":46.0037,"lng":8.9511,"nights":1,"planSummary":"Mediterranes Finale: über den Gotthard ins Tessin, Espresso auf der Piazza, Aussicht vom Monte Brè und Grotto-Küche im Fischerdorf Gandria.","plannedStops":[{"label":"Piazza della Riforma","hint":"Italianità pur — Espresso auf dem Hauptplatz unter Palazzi","time":"11:00","itemName":"Piazza della Riforma Lugano"},{"label":"Parco Ciani","hint":"Uferpark mit Palmen und Blick über den Luganersee","time":"12:00","itemName":"Parco Ciani"},{"label":"Monte Brè","hint":"Mit der Standseilbahn auf Luganos Hausberg — Seeblick von oben","time":"14:00","itemName":"Monte Brè"},{"label":"Gandria-Spaziergang","hint":"Olivenweg am Seeufer ins autofreie Fischerdorf","time":"16:30","itemName":"Sentiero di Gandria"},{"label":"Grotto-Abend","hint":"Tessiner Grotto-Küche direkt am Wasser in Gandria","time":"19:00","itemName":"Grotto dei Pescatori Gandria"}]}]$$),
('kroatien-dalmatien-zadar-dubrovnik','Dalmatien — Zadar bis Dubrovnik','Fünf Tage kroatische Adria: Meeresorgel in Zadar, Wasserfälle im Krka-Nationalpark, Diokletianpalast in Split, Riviera-Strände von Brela und zum Finale die Stadtmauern von Dubrovnik.',null,null,'PD24 Redaktion','public','completed',true,array['europe','croatia','coast','beach','culture','road-trip'],5,array['HR'],'tourism','medium',$$[{"citySlug":"hr-zadar","cityLabel":"Zadar","lat":44.1194,"lng":15.2314,"nights":1,"planSummary":"Auftakt mit dem berühmtesten Sonnenuntergang der Adria: römisches Forum, Marmorgassen und am Ufer spielt die Meeresorgel zum Abendlicht.","plannedStops":[{"label":"Altstadt-Halbinsel","hint":"Marmorglatte Gassen zwischen römischem Forum und Kirche Sv. Donat","time":"14:00","itemName":"Forum Zadar"},{"label":"Kathedrale & Glockenturm","hint":"Aufstieg auf den Campanile der Anastasia-Kathedrale für den Überblick","time":"15:30","itemName":"Katedrala Sv. Stošije Zadar"},{"label":"Abendessen","hint":"Dalmatinische Klassiker im Gassengewirr der Altstadt","time":"18:00","itemName":"Konoba Stomorica Zadar"},{"label":"Meeresorgel","hint":"Stufen am Ufer, durch die die Wellen Orgeltöne spielen","time":"19:30","itemName":"Morske Orgulje Zadar"},{"label":"Gruß an die Sonne","hint":"Leuchtende Lichtinstallation direkt neben der Meeresorgel nach Sonnenuntergang","time":"20:30","itemName":"Pozdrav Suncu Zadar"}]},{"citySlug":"hr-sibenik","cityLabel":"Šibenik & Krka","lat":43.735,"lng":15.8952,"nights":1,"planSummary":"Wasserfall-Tag im Krka-Nationalpark mit dem großen Skradinski Buk, danach die steinerne Altstadt von Šibenik mit ihrer UNESCO-Kathedrale.","plannedStops":[{"label":"Krka-Nationalpark","hint":"Holzstege über türkisen Kaskaden — früh starten, Ticket vorab buchen","time":"09:00","itemName":"Nacionalni Park Krka"},{"label":"Skradinski Buk","hint":"Die berühmteste Wasserfall-Terrasse des Parks, 17 Stufen","time":"10:00","itemName":"Skradinski Buk"},{"label":"Mittag in Skradin","hint":"Kleiner Hafenort am Parkeingang mit Konoba-Küche","time":"13:00","itemName":"Konoba Toni Skradin"},{"label":"Kathedrale des Hl. Jakob","hint":"UNESCO-Meisterwerk komplett aus Stein — mit 71 Steinköpfen an der Apsis","time":"15:30","itemName":"Katedrala Sv. Jakova Šibenik"},{"label":"Festung Barone","hint":"Abendblick über Dächer, Inseln und Kanal von der Festung","time":"18:00","itemName":"Tvrđava Barone Šibenik"}]},{"citySlug":"hr-split","cityLabel":"Split","lat":43.5081,"lng":16.4402,"nights":1,"planSummary":"Eine Stadt in einem römischen Palast: Peristyl und Kellergewölbe des Diokletianpalasts, Aussicht vom Marjan-Hügel und abends Riva-Flanieren mit Blick auf die Fähren.","plannedStops":[{"label":"Diokletianpalast","hint":"1700 Jahre altes UNESCO-Herz der Stadt — Peristyl und Kathedrale","time":"09:30","itemName":"Dioklecijanova Palača Split"},{"label":"Palast-Keller","hint":"Original erhaltene Substruktionen, Game-of-Thrones-Drehort","time":"11:00","itemName":"Podrumi Dioklecijanove Palače"},{"label":"Mittag in der Altstadt","hint":"Dalmatinische Fisch- und Peka-Gerichte hinter dem Palast","time":"13:00","itemName":"Konoba Fetivi Split"},{"label":"Marjan-Aussicht","hint":"Treppen auf den Stadthügel — Blick über Hafen, Altstadt und Inseln","time":"15:30","itemName":"Vidilica Marjan Split"},{"label":"Riva am Abend","hint":"Palmenpromenade mit Aperitif, dahinter glüht der Palast","time":"19:00","itemName":"Riva Split"}]},{"citySlug":"hr-makarska","cityLabel":"Makarska","lat":43.2969,"lng":17.0178,"nights":1,"planSummary":"Riviera-Tag unter den Felswänden des Biokovo: Kiesstrände mit Pinien, der Skywalk über dem Meer und abends Grillfisch am Hafen.","plannedStops":[{"label":"Biokovo Skywalk","hint":"Glasplattform auf 1.228 m über der Riviera — Serpentinenfahrt im Naturpark","time":"09:30","itemName":"Biokovo Skywalk"},{"label":"Punta Rata","hint":"Einer der schönsten Strände der Adria, in Brela unter Pinien","time":"12:00","itemName":"Plaža Punta Rata Brela"},{"label":"Strand-Mittag","hint":"Leichtes Mittagessen direkt über dem Wasser in Brela","time":"14:00","itemName":"Konoba Feral Brela"},{"label":"Hafenpromenade","hint":"Palmen, Kalksteinberge und Eisdielen — die Makarska-Kulisse","time":"17:00","itemName":"Riva Makarska"},{"label":"Fisch-Abend","hint":"Frischer Grillfisch und dalmatinischer Wein nahe dem Hafen","time":"19:30","itemName":"Restoran Jeny Makarska"}]},{"citySlug":"hr-dubrovnik","cityLabel":"Dubrovnik","lat":42.6507,"lng":18.0944,"nights":1,"planSummary":"Die Perle der Adria zum Finale: einmal komplett über die Stadtmauern, mit der Seilbahn auf den Srđ und ein Sundowner in der Felsenbar über dem offenen Meer.","plannedStops":[{"label":"Stadtmauern-Runde","hint":"1,9 km über den Dächern — früh starten, bevor es heiß und voll wird","time":"08:30","itemName":"Gradske Zidine Dubrovnik"},{"label":"Stradun & Altstadt","hint":"Die marmorglänzende Hauptgasse zwischen Brunnen und Glockenturm","time":"11:00","itemName":"Stradun Dubrovnik"},{"label":"Mittagspause","hint":"Fisch-Klassiker am alten Hafen","time":"13:00","itemName":"Lokanda Peskarija Dubrovnik"},{"label":"Seilbahn auf den Srđ","hint":"Panoramablick auf Altstadt, Lokrum und Elaphiten","time":"15:30","itemName":"Žičara Srđ Dubrovnik"},{"label":"Buža Bar","hint":"Sundowner in der Bar im Fels — durch ein Loch in der Stadtmauer","time":"18:30","itemName":"Buža Bar Dubrovnik"}]}]$$),
('toskana-chianti-val-dorcia','Toskana — Florenz, Chianti & Val d''Orcia','Fünf Tage Bilderbuch-Italien: Renaissance in Florenz, Stadtmauer-Radrunde in Lucca, die Türme von San Gimignano, der Campo von Siena und Zypressenalleen im Val d''Orcia — mit Wein, Pici und Pecorino.',null,null,'PD24 Redaktion','public','completed',true,array['europe','italy','food','culture','luxury','road-trip'],5,array['IT'],'tourism','high',$$[{"citySlug":"it-florenz","cityLabel":"Florenz","lat":43.7696,"lng":11.2558,"nights":1,"planSummary":"Renaissance im Schnelldurchlauf: Dom und Ponte Vecchio, ein Panino vom Kultstand und zum Sonnenuntergang der Blick vom Piazzale Michelangelo über die Stadt.","plannedStops":[{"label":"Dom & Kuppel","hint":"Brunelleschis Kuppel — das Wahrzeichen der Renaissance (Ticket vorab)","time":"14:00","itemName":"Cattedrale di Santa Maria del Fiore"},{"label":"Piazza della Signoria","hint":"Freilichtmuseum mit Palazzo Vecchio und Loggia dei Lanzi","time":"15:30","itemName":"Piazza della Signoria"},{"label":"Panino-Klassiker","hint":"Das berühmteste Schinken-Panino der Stadt — Schlange gehört dazu","time":"16:30","itemName":"All'Antico Vinaio"},{"label":"Ponte Vecchio","hint":"Die Goldschmiede-Brücke über den Arno im Abendlicht","time":"17:30","itemName":"Ponte Vecchio"},{"label":"Piazzale Michelangelo","hint":"Der Postkartenblick über Florenz zum Sonnenuntergang","time":"19:00","itemName":"Piazzale Michelangelo"}]},{"citySlug":"it-lucca","cityLabel":"Lucca","lat":43.843,"lng":10.501,"nights":1,"planSummary":"Die Stadt auf der Mauer: einmal die komplette Renaissance-Stadtmauer mit dem Rad umrunden, dann Piazza-Leben auf dem ovalen Amphitheaterplatz und Turmblick vom Torre Guinigi.","plannedStops":[{"label":"Stadtmauer-Radrunde","hint":"4,2 km baumbestandene Mauerkrone — Räder direkt an der Mauer leihen","time":"09:30","itemName":"Mura di Lucca"},{"label":"Piazza dell'Anfiteatro","hint":"Ovaler Platz auf den Fundamenten des römischen Amphitheaters","time":"11:30","itemName":"Piazza dell'Anfiteatro"},{"label":"Mittag in der Gasse","hint":"Traditionsosteria mit lucchesischen Klassikern wie Tordelli","time":"13:00","itemName":"Osteria Baralla Lucca"},{"label":"Torre Guinigi","hint":"Der Turm mit den Steineichen auf dem Dach — Blick über alle Dächer","time":"15:00","itemName":"Torre Guinigi"},{"label":"Buccellato-Pause","hint":"Luccas Rosinen-Anis-Kuchen in der Pasticceria von 1881","time":"17:00","itemName":"Pasticceria Taddeucci Lucca"}]},{"citySlug":"it-san-gimignano","cityLabel":"San Gimignano","lat":43.4674,"lng":11.0431,"nights":1,"planSummary":"Manhattan des Mittelalters: 14 Geschlechtertürme über den Weinbergen, Weltmeister-Eis auf der Piazza della Cisterna und Vernaccia-Verkostung mit Hügelblick.","plannedStops":[{"label":"Piazza della Cisterna","hint":"Der dreieckige Brunnenplatz — schönster Auftakt durch die Porta San Giovanni","time":"10:00","itemName":"Piazza della Cisterna"},{"label":"Torre Grossa","hint":"Der höchste begehbare Turm mit Blick über Türme und Weinberge","time":"11:00","itemName":"Torre Grossa San Gimignano"},{"label":"Weltmeister-Gelato","hint":"Mehrfacher Eis-Weltmeister Sergio Dondoli — Sorte Crema di Santa Fina","time":"12:30","itemName":"Gelateria Dondoli"},{"label":"Mittag mit Aussicht","hint":"Toskanische Küche mit Terrassenblick über das Elsa-Tal","time":"13:30","itemName":"Ristorante Bel Soggiorno San Gimignano"},{"label":"Vernaccia-Tasting","hint":"Der weiße Klassiker der Stadt, verkostet in der Rocca di Montestaffoli","time":"16:00","itemName":"Rocca di Montestaffoli"}]},{"citySlug":"it-siena","cityLabel":"Siena","lat":43.3188,"lng":11.3308,"nights":1,"planSummary":"Die gotische Rivalin von Florenz: der muschelförmige Campo, der Zebra-Dom und abends Pici mit Wildschweinragù in einer Osteria im Contraden-Viertel.","plannedStops":[{"label":"Piazza del Campo","hint":"Der berühmteste Platz Italiens — Schauplatz des Palio-Pferderennens","time":"09:30","itemName":"Piazza del Campo"},{"label":"Torre del Mangia","hint":"400 Stufen über den Campo — der klassische Siena-Blick","time":"10:30","itemName":"Torre del Mangia"},{"label":"Dom von Siena","hint":"Schwarz-weiß gestreiftes Gotik-Meisterwerk mit Marmor-Fußboden","time":"12:30","itemName":"Duomo di Siena"},{"label":"Panforte-Pause","hint":"Sienas Gewürzkuchen in der historischen Konditorei","time":"15:00","itemName":"Pasticceria Nannini Siena"},{"label":"Osteria-Abend","hint":"Pici al ragù di cinghiale in der Traditionsosteria","time":"19:00","itemName":"Osteria Le Logge Siena"}]},{"citySlug":"it-pienza","cityLabel":"Pienza & Val d'Orcia","lat":43.077,"lng":11.6789,"nights":1,"planSummary":"Finale in der UNESCO-Hügellandschaft: Pecorino in Pienza, die Zypressenallee von Monticchiello, Weinprobe in Montepulciano und der berühmteste Fotospot der Toskana bei San Quirico.","plannedStops":[{"label":"Pienza-Altstadt","hint":"Die ideale Renaissance-Stadt von Papst Pius II. — mit Pecorino-Läden","time":"09:30","itemName":"Centro Storico Pienza"},{"label":"Pecorino-Verkostung","hint":"Käseladen mit Reifekeller und Blick übers Val d'Orcia","time":"11:00","itemName":"La Taverna del Pecorino Pienza"},{"label":"Zypressen von San Quirico","hint":"Die ikonische Zypressengruppe in den Hügeln — der Toskana-Fotospot","time":"13:00","itemName":"Cipressi di San Quirico d'Orcia"},{"label":"Montepulciano","hint":"Weinstadt auf dem Hügel — Vino Nobile in historischen Kellern","time":"15:00","itemName":"Cantina Contucci Montepulciano"},{"label":"Sunset in Monticchiello","hint":"Zypressen-Serpentine und Abendlicht über dem Val d'Orcia","time":"18:30","itemName":"Cipressi di Monticchiello"}]}]$$),
('griechenland-peloponnes-antike-meer','Peloponnes — Antike, Küste & Mani','Vier Tage griechisches Festland: Akropolis-Auftakt in Athen, das Amphitheater von Epidauros, Venedig-Flair in Nafplio, die Felsenstadt Monemvasia und wilde Steintürme in der Mani.',null,null,'PD24 Redaktion','public','completed',true,array['europe','greece','coast','culture','beach','road-trip'],4,array['GR'],'tourism','medium',$$[{"citySlug":"gr-athen","cityLabel":"Athen","lat":37.9838,"lng":23.7275,"nights":1,"planSummary":"Ein Nachmittag Athen als Auftakt: Akropolis im weichen Licht, Bummel durch Plaka und Anafiotika und abends Souvlaki mit Akropolis-Blick auf der Dachterrasse.","plannedStops":[{"label":"Akropolis","hint":"Parthenon und Erechtheion — nachmittags wird es leerer und das Licht weich","time":"15:00","itemName":"Akropolis Athen"},{"label":"Anafiotika","hint":"Weißgekalkte Inselgassen mitten unter dem Akropolisfelsen","time":"17:00","itemName":"Anafiotika"},{"label":"Plaka-Bummel","hint":"Die Altstadt zu Füßen der Akropolis mit Läden und Tavernen","time":"18:00","itemName":"Plaka Athen"},{"label":"Taverne des Abends","hint":"Klassische Taverne in Psiri, seit Jahrzehnten eine Institution","time":"19:30","itemName":"Taverna tou Psiri"},{"label":"Areopag-Fels","hint":"Der Sunset-Fels gegenüber der Akropolis — Athen bei Nacht","time":"21:00","itemName":"Areopagus Athen"}]},{"citySlug":"gr-nafplio","cityLabel":"Nafplio & Epidauros","lat":37.5674,"lng":22.8014,"nights":1,"planSummary":"Erst das perfekt erhaltene Amphitheater von Epidauros, dann Griechenlands eleganteste Kleinstadt: Palamidi-Festung, venezianische Gassen und Gelato an der Hafenpromenade.","plannedStops":[{"label":"Theater von Epidauros","hint":"UNESCO-Theater mit legendärer Akustik — ein Flüstern trägt bis Reihe 55","time":"09:30","itemName":"Theater von Epidauros"},{"label":"Palamidi-Festung","hint":"999 Stufen oder Serpentinenstraße — Blick über den Argolischen Golf","time":"12:00","itemName":"Palamidi Nafplio"},{"label":"Altstadt-Mittag","hint":"Griechische Klassiker unter Bougainvillea in der Fußgängerzone","time":"14:00","itemName":"Taverna To Omorfo Tavernaki Nafplio"},{"label":"Syntagma-Platz & Gassen","hint":"Venezianische Fassaden, Boutiquen und das erste Parlament Griechenlands","time":"16:00","itemName":"Plateia Syntagmatos Nafplio"},{"label":"Arvanitia-Promenade","hint":"Uferweg um den Festungsfelsen zum Sonnenuntergang, Blick auf Bourtzi","time":"18:30","itemName":"Arvanitia Promenade Nafplio"}]},{"citySlug":"gr-monemvasia","cityLabel":"Monemvasia","lat":36.6871,"lng":23.0428,"nights":1,"planSummary":"Das Gibraltar Griechenlands: eine komplett erhaltene byzantinische Felsenstadt, nur durch ein Tor erreichbar — Gassen, Kirchen, Meerblick und abends Wein aus der Malvasia-Traube.","plannedStops":[{"label":"Durch das Stadttor","hint":"Autofrei — durch das einzige Tor in die versteckte Unterstadt","time":"10:00","itemName":"Kastro Monemvasia"},{"label":"Oberstadt & Agia Sophia","hint":"Aufstieg zur byzantinischen Kirche an der Klippenkante","time":"11:30","itemName":"Agia Sophia Monemvasia"},{"label":"Mittag auf der Terrasse","hint":"Taverne mit Meerblick-Terrasse in der Unterstadt","time":"13:30","itemName":"Taverna Matoula Monemvasia"},{"label":"Baden am Felsen","hint":"Badeleitern direkt am Fels beim Portello-Tor","time":"15:30","itemName":"Portello Monemvasia"},{"label":"Malvasia-Wein","hint":"Der Süßwein, der der Stadt den Namen verdankt — Verkostung im Ort","time":"18:00","itemName":"Monemvasia Winery"}]},{"citySlug":"gr-kardamili","cityLabel":"Kardamili & Mani","lat":36.8873,"lng":22.2331,"nights":1,"planSummary":"Wildes Finale in der Mani: Steinturm-Dörfer, Zypressen und Olivenhaine unterm Taygetos, Badebucht mit Kieselstrand und Taverne direkt über dem Wasser.","plannedStops":[{"label":"Alt-Kardamili","hint":"Turmhäuser und die befestigte Kirche der Familie Mourtzinos","time":"10:00","itemName":"Old Kardamili"},{"label":"Foneas Beach","hint":"Kieselbucht mit Fel