iu"},{"label":"Lügenbrücke","hint":"Gusseiserne Brücke von 1859 — die Legende erzählt der Guide","time":"12:00","itemName":"Podul Minciunilor Sibiu"},{"label":"Mittag am Kleinen Ring","hint":"Moderne siebenbürgische Küche im alten Handwerkerhaus","time":"13:00","itemName":"Crama Sibiul Vechi"},{"label":"ASTRA-Freilichtmuseum","hint":"Windmühlen und Holzkirchen im größten Freilichtmuseum Rumäniens","time":"15:30","itemName":"Muzeul ASTRA Sibiu"}]},{"citySlug":"ro-balea","cityLabel":"Transfăgărășan & Bâlea Lac","lat":45.6036,"lng":24.6173,"nights":1,"planSummary":"Der Fahrtag, für den die Reise gemacht ist: 90 Serpentinen-Kilometer über die Transfăgărășan zum Gletschersee Bâlea Lac — nur Juli bis Oktober offen, Wetterfenster nutzen.","plannedStops":[{"label":"Serpentinen Nordrampe","hint":"Die berühmte Kehrenlandschaft — Aussichtspunkt an der Kaskade","time":"09:30","itemName":"Transfăgărășan Nordrampe"},{"label":"Bâlea-Wasserfall","hint":"Zwischenstopp an der Seilbahnstation am Wasserfall","time":"11:00","itemName":"Cascada Bâlea"},{"label":"Bâlea Lac","hint":"Gletschersee auf 2.034 m im Kessel der Făgăraș-Berge","time":"12:30","itemName":"Bâlea Lac"},{"label":"See-Rundweg","hint":"Kurze Kammwanderung über dem See — Wetter beachten","time":"14:00","itemName":"Bâlea Lac Rundweg"},{"label":"Vidraru-Staudamm","hint":"Über den Tunnel zur Südseite — 166-Meter-Bogenstaumauer","time":"16:30","itemName":"Barajul Vidraru"}]}]$$),
('frankreich-normandie-bretagne','Normandie & Bretagne — Kreidefelsen bis Rosa Granit','Sechs Tage französischer Norden: die Alabasterklippen von Étretat, Calvados und Fachwerk in Honfleur, die D-Day-Strände, der Mont-Saint-Michel in der Bucht, Korsarenstadt Saint-Malo und die rosa Felsen von Ploumanac''h.',null,null,'PD24 Redaktion','public','completed',true,array['europe','france','coast','nature','food','road-trip'],6,array['FR'],'tourism','medium',$$[{"citySlug":"fr-etretat","cityLabel":"Étretat","lat":49.707,"lng":0.205,"nights":1,"planSummary":"Die Alabasterküste zum Auftakt: Felsbögen und die Nadel von Étretat von beiden Klippen aus, dazwischen Moules-frites mit Blick auf den Kiesstrand.","plannedStops":[{"label":"Falaise d'Aval","hint":"Der berühmte Felsbogen mit der Aiguille — Monets Lieblingsmotiv","time":"14:00","itemName":"Falaise d'Aval Étretat"},{"label":"Klippenwanderung","hint":"Über den Zöllnerpfad Richtung Manneporte, dem größten Bogen","time":"15:30","itemName":"Manneporte Étretat"},{"label":"Jardins d'Étretat","hint":"Skulpturengarten über der Falaise d'Amont mit Küstenblick","time":"17:00","itemName":"Les Jardins d'Étretat"},{"label":"Moules am Strand","hint":"Muscheln und Cidre an der Strandpromenade","time":"19:00","itemName":"Le Homard Bleu Étretat"},{"label":"Sunset am Kies","hint":"Abendlicht auf den weißen Klippen vom Kiesstrand aus","time":"20:30","itemName":"Plage d'Étretat"}]},{"citySlug":"fr-honfleur","cityLabel":"Honfleur","lat":49.4194,"lng":0.2332,"nights":1,"planSummary":"Der malerischste Hafen Frankreichs: schmale Schieferfassaden am Vieux Bassin, die hölzerne Katharinenkirche und Calvados-Verkostung — die Impressionisten wussten, warum.","plannedStops":[{"label":"Vieux Bassin","hint":"Das Postkartenmotiv: alte Hafenbecken mit Schieferhäusern","time":"10:00","itemName":"Vieux Bassin Honfleur"},{"label":"Sainte-Catherine","hint":"Größte Holzkirche Frankreichs, von Schiffszimmerern gebaut","time":"11:00","itemName":"Église Sainte-Ca